"""Responsabilidad Personal y Social EPJA Media N1 y N2, módulo 2: responsabilidad, gestión y proactividad; pasos de un proyecto de participación; enfoque de género e igualdad de oportunidades; comunicar y rediseñar proyectos (OAD-05 a OAD-08). Todo en papel; personajes, cifras y casos ficticios."""
from __future__ import annotations

from hc_common import make_build

MATERIALS = "Papel y lápiz. Todo se resuelve con lo escrito en la ficha. Los personajes, los casos y las cifras son de ejemplo e inventados: no hace falta contar nada personal ni mostrar lo que escribas sobre ti."
build = make_build(MATERIALS)

O5 = "EPJA-RPSO-NM1y2-OAD-05"
O6 = "EPJA-RPSO-NM1y2-OAD-06"
O7 = "EPJA-RPSO-NM1y2-OAD-07"
O8 = "EPJA-RPSO-NM1y2-OAD-08"
PRIOR = ["Ya organizo tareas en mi vida diaria: en casa, en el trabajo o en la comunidad.", "Puedo leer una ficha corta y responder por escrito o en voz alta."]


def K(oa, n, F, use, explain, vocab, worked, mistakes, T, ctx, sc, op, rf, ex_, prior=None):
    stmt, example, crit, evid, err, fb = op
    build(oa, n, F, use=use, prior=prior or PRIOR, explain=explain, vocab=vocab, worked=worked, mistakes=mistakes, T=T, ctx=ctx, sc=sc,
          op=(stmt, example, crit, evid, err, fb), reinforce=rf, extend=ex_)


